insert into public.polls (question, option_a, option_b, blurb, era, gender_lean, published_at, sort_index)
values
  ('小学校に上がった年のヒーロー、見ていたのは？', '秘密戦隊ゴレンジャー', '仮面ライダーストロンガー', 'どちらも1975年4月に始まった。集団戦の新しさか、ライダーの王道か、教室で毎週もめた話題。', '小学校', 'male', now() - interval '24 hours', 0),
  ('キャンディ・キャンディ、心を寄せたのは？', 'アンソニー', 'テリィ', '放送は1976年から1979年、小学校の低中学年。丘の上の王子様か、反抗的な彼かで割れた。', '小学校', 'female', now() - interval '18 hours', 1),
  ('スーパーカーブーム、下敷きにしていたのは？', 'ランボルギーニ・カウンタック', 'フェラーリ512BB', '1977年前後、小学校の中学年を直撃したブーム。親のカメラを借りて展示会に走った人も多かった。', '小学校', 'male', now() - interval '12 hours', 2),
  ('毎月買っていた少女まんが誌は？', 'りぼん', 'なかよし', '付録の便箋やシールが目当てだった小学生時代。友達と交換して両方を読む工夫もしていた。', '小学校', 'female', now() - interval '6 hours', 3),
  ('小学生の頃に乗っていた自転車は？', 'フラッシャー付きの多段変速', 'シンプルなセミドロップ', '後輪の上でランプが流れるフラッシャー車は1970年代後半の憧れ。値段の差で親との交渉が続いた。', '小学校', 'male', now() + interval '3 days', 4),
  ('筆箱やハンカチで選んだのは？', 'ハローキティ', 'キキとララ', 'キティは1974年、キキとララは1976年の登場。文具売り場の前で真剣に迷った小学生時代。', '小学校', 'female', now() + interval '6 days', 5),
  ('胸が熱くなったのはどっち？', '宇宙戦艦ヤマト', '機動戦士ガンダム', '劇場版ヤマトは1977年の小三、ガンダム放送は1979年の小四。二年差で世界観がまるで違った。', '小学校', 'male', now() + interval '10 days', 6),
  ('日曜夜の名作劇場、泣いたのは？', 'フランダースの犬', '赤毛のアン', 'フランダースは1975年、アンは1979年の放送。小学校の六年間がまるごと重なっている。', '小学校', 'female', now() + interval '13 days', 7),
  ('初めて夢中になった電子ゲームは？', '喫茶店のスペースインベーダー', '任天堂のゲーム＆ウオッチ', 'インベーダーは1978年、ゲーム＆ウオッチは1980年4月の発売。小学校の高学年が分かれ目だった。', '小学校', 'male', now() + interval '17 days', 8),
  ('ピンク・レディー、真似していたのは？', 'ミー', 'ケイ', '1976年のデビューから1981年の解散まで、ちょうど小学校時代と重なる。振り付けは必修だった。', '小学校', 'female', now() + interval '20 days', 9),
  ('毎月届くのが待ち遠しかったのは？', '学研の「科学」', '学研の「学習」', '学研のおばちゃんが運んできた二冊。付録の実験キット目当てか、まんが記事目当てかで分かれた。', '小学校', 'male', now() + interval '24 days', 10),
  ('花の中三トリオで好きだったのは？', '山口百恵', '桜田淳子', '小学生の頃の歌番組の主役だった二人。百恵さんの引退は1980年、こちらが小学校最後の年。', '小学校', 'female', now() + interval '27 days', 11),
  ('1979年の口裂け女、当時のあなたは？', '本気で怖くて回り道した', '作り話だと思っていた', '小学校の中学年の頃に全国へ広まった噂。ポマードと唱えれば逃げるという対策まで出回った。', '小学校', 'male', now() + interval '31 days', 12),
  ('ガラスの仮面、応援していたのは？', '北島マヤ', '姫川亜弓', '連載開始は1976年。才能でぶつかる二人のどちらに感情移入するかで性格が出ると言われた。', '小学校', 'female', now() + interval '34 days', 13),
  ('ルービックキューブ、結局どうだった？', '六面そろえられた', '一面で力尽きた', '日本発売は1980年、小学校最後の年。シールを貼り替えて完成させたと言い張る猛者もいた。', '小学校', 'male', now() + interval '38 days', 14),
  ('ベルサイユのばら、心を寄せたのは？', 'オスカル', 'マリー・アントワネット', 'アニメ放送は1979年から1980年、小学校の高学年の頃。宝塚の初演は1974年で再演も続いた。', '小学校', 'female', now() + interval '41 days', 15),
  ('小遣いを注ぎ込んだのは？', 'ガンプラ', 'ラジコンカー', '1981年前後は模型店に行列ができた時代。塗装して飾る派と走らせる派で夢中の方向が違った。', '中学', 'male', now() + interval '45 days', 16),
  ('聖子派？ 明菜派？', '松田聖子', '中森明菜', '聖子のデビューは1980年、明菜は1982年で中学二年の年。歌番組のたびに教室で論争になった。', '中学', 'female', now() + interval '48 days', 17),
  ('深夜に布団の中で聴いていたのは？', 'ビートたけしのオールナイトニッポン', '笑福亭鶴光のオールナイトニッポン', 'たけしの担当開始は1981年、中学に上がった年。翌日の教室は前夜のネタで持ちきりだった。', '中学', 'male', now() + interval '52 days', 18),
  ('たのきんトリオで夢中になったのは？', '田原俊彦', '近藤真彦', '金八先生をきっかけに1980年から大ブレイク。小学校の終わりから中学にかけての大事件だった。', '中学', 'female', now() + interval '55 days', 19),
  ('少年ジャンプで真っ先に読んでいたのは？', 'キン肉マン', 'キャプテン翼', '連載開始はキン肉マンが1979年、翼が1981年。中学の教室では消しゴム派と部活派に分かれた。', '中学', 'male', now() + interval '59 days', 20),
  ('歌本目当てに買っていたのは？', '明星', '平凡', '付録の歌本で覚えた歌詞は今でも出てくる。切り抜きを下敷きに挟むのが中学の作法だった。', '中学', 'female', now() + interval '62 days', 21),
  ('学生服、こだわったのは？', '短ラン', '長ラン', '校内暴力が社会問題になった1980年代前半。丈と裏地の柄で自己主張をした世代でもあった。', '中学', 'male', now() + interval '66 days', 22),
  ('中学の頃の髪型は？', '聖子ちゃんカット', '肩までのストレート', '1980年代の前半に大流行した聖子ちゃんカット。校則との折り合いに苦労した人も多かった。', '中学', 'female', now() + interval '69 days', 23),
  ('カセットテープ、買っていたのは？', 'TDK', 'マクセル', 'エアチェック全盛の中学時代。ノーマルかハイポジかも含めて、店頭で長々と悩んだものだった。', '中学', 'male', now() + interval '73 days', 24),
  ('胸が高鳴ったのは？', 'ときめきトゥナイト', '生徒諸君！', 'ときめきトゥナイトの連載開始は1982年。魔界の恋か、熱血の学園ものかで好みが分かれた。', '中学', 'female', now() + interval '76 days', 25),
  ('聴きたい曲、どうやって手に入れた？', '貸レコードで借りてダビング', 'FM放送をエアチェック', '貸レコードは1980年に登場し中高生へ一気に普及。FM誌片手の録音派も最後まで根強かった。', '中学', 'male', now() + interval '80 days', 26),
  ('あの頃、夢中で見たドラマは？', 'スチュワーデス物語', '積み木くずし', '積み木くずしは1983年の春、スチュワーデス物語は同じ年の秋。中学三年の話題を独占した。', '中学', 'female', now() + interval '83 days', 27),
  ('相撲で応援していたのは？', '千代の富士', '北の湖', '千代の富士の横綱昇進は1981年、中学一年の夏。憎らしいほど強い北の湖との対比が話題だった。', '中学', 'male', now() + interval '87 days', 28),
  ('花の82年組で応援したのは？', '小泉今日子', '堀ちえみ', '1982年は明菜も早見優も出た当たり年。中学二年の教室はアイドル論争であふれていた。', '中学', 'female', now() + interval '90 days', 29),
  ('土曜夜のプロレス、目当ては？', '初代タイガーマスク', 'アントニオ猪木', 'タイガーマスクの登場は1981年4月。四次元殺法に沸く中学生と、猪木の闘魂派とで分かれた。', '中学', 'male', now() + interval '94 days', 30),
  ('お姉さん的アイドル、好きだったのは？', '河合奈保子', '柏原芳恵', 'どちらも1980年前後のデビュー。同級生の男子が誰の下敷きを持っているかも気になった。', '中学', 'female', now() + interval '97 days', 31),
  ('中学時代、強烈だった甲子園は？', '池田高校のやまびこ打線', 'PL学園のKKコンビ', '池田は1982年夏に頂点、PLは1983年夏に優勝。ひとつ上の学年の桑田・清原に衝撃を受けた。', '中学', 'male', now() + interval '101 days', 32),
  ('歌番組はどっちを見ていた？', 'ザ・ベストテン', '夜のヒットスタジオ', 'ランキングの緊張感か、生放送の華やかさか。曜日が違うのに家族でチャンネルを取り合った。', '中学', 'female', now() + interval '104 days', 33),
  ('ファミコン、家にあった？', '買ってもらえた', '友達の家でやった', '発売は1983年7月、中学三年の夏。高校受験と重なって親の許可が下りない家も多かった。', '中学', 'male', now() + interval '108 days', 34),
  ('中三の終わりに現れて騒然としたのは？', 'チェッカーズ', '吉川晃司', 'チェッカーズは1983年の秋、吉川晃司は1984年2月のデビュー。卒業前後の教室を騒がせた。', '中学', 'female', now() + interval '111 days', 35),
  ('高校の頃、買っていた音楽は？', 'レコード', 'CD', 'CDの登場は1982年だが、高校時代はまだプレーヤーが高価。ジャケットの大きさで選ぶ人もいた。', '高校', 'male', now() + interval '115 days', 36),
  ('スケバン刑事、しっくりきたのは？', '斉藤由貴', '南野陽子', '初代は1985年の春、二代目は同じ年の秋から。高校二年の途中でヒロインが交代した番組。', '高校', 'female', now() + interval '118 days', 37),
  ('歌詞が刺さったのはどっち？', '尾崎豊', '佐野元春', '尾崎のデビューは1983年、「卒業」は1985年の高校時代。言葉の熱さか都会的な軽さかで割れた。', '高校', 'male', now() + interval '122 days', 38),
  ('おニャン子クラブ、あなたは？', '夢中で見ていた', '冷めて見ていた', '夕やけニャンニャンの開始は1985年、高校二年の春。素人っぽさへの賛否がはっきり割れた。', '高校', 'female', now() + interval '125 days', 39),
  ('高校の頃、続きが気になったのは？', '北斗の拳', 'シティーハンター', '北斗は1983年、シティーハンターは1985年の連載開始。暴力の美学か軽妙さかで好みが出た。', '高校', 'male', now() + interval '129 days', 40),
  ('大映ドラマで泣いたのは？', 'スクール☆ウォーズ', '不良少女とよばれて', '不良少女は1984年の春、スクール☆ウォーズは同じ年の秋。高校一年の夜を独占した二本。', '高校', 'female', now() + interval '132 days', 41),
  ('高校の頃、よく聴いていたのは？', '洋楽（ベストヒットUSA）', '邦楽（ザ・ベストテン）', 'ベストヒットUSAの放送開始は1981年。小林克也の紹介で洋楽に目覚めた高校生が続出した。', '高校', 'male', now() + interval '136 days', 42),
  ('高校の頃、めくっていた雑誌は？', 'JJ', 'Olive', 'Oliveの創刊は1982年。お姉さん路線のJJか、少女らしいオリーブ少女かで方向が分かれた。', '高校', 'female', now() + interval '139 days', 43),
  ('バンドブームで聴いていたのは？', 'BOØWY', 'レベッカ', 'どちらも1985年前後に人気が沸騰。ギターを買ってコピーに挑んだ高校生が一気に増えた。', '高校', 'male', now() + interval '143 days', 44),
  ('ひとりで聴きたくなるのは？', '松任谷由実', '中島みゆき', 'どちらも高校時代の夜に染みた歌声。明るさの裏側の描き方がまるで違うと語り合った。', '高校', 'female', now() + interval '146 days', 45),
  ('16歳になって、原付免許は？', 'すぐ取りに行った', '校則で諦めた', '高校一年は1984年。三ない運動が広がり、免許取得を禁じる学校が全国に多かった時期だった。', '高校', 'male', now() + interval '150 days', 46),
  ('高校の頃の洋楽といえば？', 'マイケル・ジャクソン', 'マドンナ', 'スリラーは1982年末から世界を席巻し、マドンナは1985年に日本でも大ブレイクした。', '高校', 'female', now() + interval '153 days', 47),
  ('あの頃の三塁手、好きだったのは？', '掛布雅之', '原辰徳', '1985年の阪神優勝は高校二年の秋。バックスクリーン三連発に日本中が沸いた年でもあった。', '高校', 'male', now() + interval '157 days', 48),
  ('あの頃、文通相手は？', 'いた', 'いなかった', '雑誌の文通欄で相手を探した時代。切手を貼って返事を待つ時間そのものが楽しみだった。', '高校', 'female', now() + interval '160 days', 49),
  ('共通一次試験、受けた？', '受けた', '受けていない', '現役なら1987年1月の受験。センター試験に変わる前の、五教科七科目の共通一次世代にあたる。', '高校', 'male', now() + interval '164 days', 50),
  ('高校を出たあとの進路は？', '進学した', '就職した', '卒業は1987年。女性の四年制大学進学がまだ少なく、短大や就職を選ぶ人も多かった時代。', '高校', 'female', now() + interval '167 days', 51),
  ('二十代の頃、憧れた車は？', 'トヨタ・ソアラ', 'ホンダ・プレリュード', '1980年代後半のデートカー論争。高級路線か、手が届く二ドアクーペかで意見が割れた。', '社会人', 'male', now() + interval '171 days', 52),
  ('卒業前後に登場して騒がれたのは？', '少年隊', '光GENJI', '少年隊のデビューは1985年の暮れ、光GENJIは1987年の夏。妹や弟と好みが分かれた家も多い。', '社会人', 'female', now() + interval '174 days', 53),
  ('二十代の休日、出かけた先は？', 'スキー場', '海', '「私をスキーに連れてって」の公開は1987年。板を積んで夜通し走る若者が急増した時代。', '社会人', 'male', now() + interval '178 days', 54),
  ('東京ラブストーリー、気持ちが寄ったのは？', '赤名リカ', '関口さとみ', '放送は1991年、二十代前半の冬。まっすぐなリカと控えめなさとみで見事に意見が割れた。', '社会人', 'female', now() + interval '181 days', 55),
  ('ドラゴンクエストIII、発売日は？', '並んで買った', '並ばなかった', '1988年2月の発売日は社会現象になった。学校や職場を抜け出す人が出て報道されるほどだった。', '社会人', 'male', now() + interval '185 days', 56),
  ('二十代の頃の服装は？', '肩パッドやボディコン', 'ナチュラルなカジュアル', '1980年代の終わりから1990年代初めの空気。同じ年でも街と職場で装いがはっきり違った。', '社会人', 'female', now() + interval '188 days', 57),
  ('二十代の頃、歌う場所は？', 'カラオケボックス', 'スナックや宴会場', 'カラオケボックスが全国へ広がったのは1980年代の終わり。それまで歌は人前で披露するものだった。', '社会人', 'male', now() + interval '192 days', 58),
  ('二十代の頃のクリスマスは？', '特別な予定を立てた', 'いつも通り過ごした', 'バブル期のイブは予約合戦の代名詞。話題に乗る人と、静かに距離を置く人に分かれた。', '社会人', 'female', now() + interval '195 days', 59)
