insert into public.quiz_questions (question, choices, answer_index, explanation, era, gender_lean)
values
  ('1977年に創刊された「コロコロコミック」を初めて手にしたとき、いちばん驚いたのは？', '["電話帳のように分厚かった", "全ページがカラーだった", "毎号シールが付いていた", "週刊誌だった"]'::jsonb, 0, '創刊号は約400ページ。ランドセルに入れると肩が痛くなる厚さで、ドラえもんが何本も読めた。駄菓子屋の店先で回し読みされた一冊。', '小学校', 'male'),
  ('ファミコンでカセットの画面が乱れたとき、日本中の子どもがやっていた「儀式」は？', '["カセットの端子に息を吹きかけた", "本体を濡れた布で拭いた", "カセットを冷蔵庫で冷やした", "コントローラーを抜き差しした"]'::jsonb, 0, '端子の接触不良が原因なので、実は息の水分は逆効果。それでもフーッと吹いて挿し直すと直る気がして、家族全員が同じ動作をしていた。', '中学校', 'male'),
  ('初代「ドラゴンクエスト」で、続きから遊ぶために必要だったのは？', '["画面の「ふっかつのじゅもん」をノートに書き写す", "電源を切らずにおく", "専用のセーブカードを買う", "カセットに電池を入れる"]'::jsonb, 0, 'ひらがなの長い呪文を書き写し、次に一字ずつ打ち込む。「い」と「り」、「ぬ」と「ね」を書き間違えて世界が消えた夜を、多くの人が経験した。', '高校', 'male'),
  ('喫茶店のテーブル型インベーダーゲーム。順番待ちを主張するために、みんながやっていたのは？', '["台の縁に100円玉を並べて置いた", "店員に整理券をもらった", "ノートに名前を書いた", "くじを引いた"]'::jsonb, 0, 'ガラス面の手前に100円玉を並べるのが、誰が決めたわけでもない全国共通のルール。並んだ枚数が、そのまま順番待ちの列だった。', '小学校', 'male'),
  ('ブルートレインブームのとき、子どもたちが早朝の駅で狙っていたものは？', '["機関車の先頭に付いた絵入りヘッドマーク", "車掌の帽子", "切符の日付の刻印", "食堂車のメニュー"]'::jsonb, 0, '「はやぶさ」「富士」「さくら」。機関車の顔に付く絵入りのヘッドマークを撮るために、ポケットカメラを握りしめて始発前の暗いホームに立っていた。', '小学校', 'male'),
  ('1970年代の「フラッシャー付き自転車」で、いちばんの自慢ポイントは？', '["後部のランプが流れるように点滅した", "タイヤが光った", "走ると音楽が鳴った", "折りたたんで持ち運べた"]'::jsonb, 0, '後ろに付いた五連・六連のランプが順番に流れて光る。実用性はほぼ皆無なのに、これが無いと近所の自転車集団で肩身が狭かった。', '小学校', 'male'),
  ('1980年に発売された最初のガンプラを手に入れるため、当時の子どもがしたことは？', '["開店前から模型店の前に並んだ", "抽選ハガキを出した", "予約券が学校で配られた", "デパートの福袋を買った"]'::jsonb, 0, '三百円の1/144ガンダムを求めて、朝から模型店に行列。売り切れると人気のない量産型だけが棚に残り、それでも買って帰った。', '小学校', 'male'),
  ('教室や布団の上でのプロレスごっこ。「四の字固め」をかけられた側の降参の合図は？', '["床や畳を手で何度も叩いた", "「まいった」と三回叫んだ", "笛を鳴らした", "静かに手を挙げた"]'::jsonb, 0, 'テレビの通り、バンバンと床を叩けばギブアップ。それでも技を解かない子がいて、本気の喧嘩に発展するのが放課後の定番だった。', '小学校', 'male'),
  ('学研の「科学」と「学習」は、どうやって家に届いた？', '["「学研のおばちゃん」が家や学校まで届けに来た", "書店で予約して受け取った", "給食の時間に配られた", "郵便局まで取りに行った"]'::jsonb, 0, '販売員の女性が毎月配達に来る仕組み。「科学」の付録の実験キット目当てで、両方取っている子は教室でちょっとうらやましがられた。', '小学校', 'male'),
  ('週刊少年ジャンプは月曜発売。それでも中学生が週末にやっていたことは？', '["「早売り」する店を探して土日に買った", "学校の購買で予約した", "図書室で借りた", "駅の売店に木曜から並んだ"]'::jsonb, 0, '流通の都合で土曜や日曜に店頭へ出す本屋があり、その一軒を知っている子はクラスの英雄。先にネタバレを言うと本気で怒られた。', '中学校', 'male'),
  ('1979年に全国へ広まった「口裂け女」。出会ったときの撃退法として信じられていたのは？', '["「ポマード」と三回唱える", "塩をまく", "手鏡を見せる", "「かごめかごめ」を歌う"]'::jsonb, 0, 'べっこう飴を投げる、という説も並行して流行した。集団下校になった学校もあり、大人が真顔で注意を促した最初の都市伝説だった。', '小学校', 'male'),
  ('駄菓子屋の「当たり付き」で、当たりが出たときの作法は？', '["その場で同じ商品をもう一つもらえた", "現金で十円返ってきた", "店の壁に名前が貼り出された", "次回まで取っておいた"]'::jsonb, 0, '当たり棒やアタリの印を店のおばちゃんに見せると、無言でもう一本。連続で当てた日の帰り道は、世界を制した気分で歩いていた。', '小学校', 'male'),
  ('高校生のバイクを規制した「三ない運動」。禁じられた三つは？', '["免許を取らせない・買わせない・運転させない", "乗らない・貸さない・改造しない", "二人乗り・夜間走行・遠出をしない", "見ない・聞かない・話さない"]'::jsonb, 0, '1982年に全国高等学校PTA連合会が決議し、あなたたちの高校時代を直撃した。隠れて免許を取り、発覚して停学になる同級生が必ずいた。', '高校', 'male'),
  ('高校生の学生カバン（革の手提げ）で、当時流行った加工は？', '["中身を出して極限まで薄く潰した", "わざと膨らませて厚くした", "白いペンキで塗った", "持ち手を伸ばして肩掛けにした"]'::jsonb, 0, '踏んだり水に濡らしたりして、教科書がほとんど入らない厚さにする。中身は筆箱と弁当だけ。教科書は学校の机に置きっぱなしだった。', '高校', 'male'),
  ('卒業式の日、男子の学生服から真っ先に無くなったものは？', '["上から二番目のボタン", "襟の校章", "袖のボタン全部", "名札"]'::jsonb, 0, '心臓にいちばん近いから、という理由で第二ボタンが人気だった。渡す側ももらえない側も、あの日だけは校舎の裏がざわついていた。', '高校', 'male'),
  ('ラジオから流れる曲をカセットに録音する「エアチェック」。最大の敵は？', '["曲の終わりにDJが喋り出すこと", "テープが伸びること", "電池が切れること", "停電"]'::jsonb, 0, '曲の頭から録るために、指を録音ボタンに置いて待機する。最後まで完璧に録れたテープは宝物で、友達にダビングして貸し借りした。', '中学校', 'male'),
  ('1980年代に急増した「貸レコード屋」。借りたレコードを、家でどうした？', '["カセットテープにダビングした", "そのまま友達に又貸しした", "ジャケットだけコピーした", "針を新品に替えて返した"]'::jsonb, 0, '借りた日にすぐ録音して翌日返す。カセットのラベルに曲名を手書きし、A面B面の曲順に悩んでいる時間が、いちばん楽しかった。', '高校', 'male'),
  ('スーパーカーブームの頃、展示会に向かう子どもが必ず持って行ったものは？', '["カメラ", "双眼鏡", "スケッチブック", "虫かご"]'::jsonb, 0, 'ポケットカメラにフィルムを詰めて、デパートの屋上や河川敷の展示会へ。カウンタックのドアが上に開く瞬間、人垣から歓声が上がった。', '小学校', 'male'),
  ('エポック社の「野球盤」に付いていた、投手側の必殺技は？', '["消える魔球", "分身魔球", "大回転投法", "ジャイロボール"]'::jsonb, 0, 'レバーを引くと盤面に穴が開き、ボールがバットの手前で沈む。使うと本気で怒られるので、暗黙の「一試合一回まで」ルールがあった。', '小学校', 'male'),
  ('ビックリマンチョコの「ヘッド」と呼ばれる当たりシールの特徴は？', '["光を反射してキラキラ光った", "甘い香りがした", "二重に重なっていた", "裏が金色だった"]'::jsonb, 0, 'スーパーゼウスやヘッドロココ。1985年に始まった悪魔VS天使シリーズで、光る一枚のために弟や妹が箱ごと買い込んでいた。', '高校', 'male'),
  ('リリアンで編み上がった長い紐は、たいていどうなった？', '["使い道がないまま、ひたすら長く編み続けた", "給食袋の紐になった", "上履き入れに縫い付けた", "学校に提出した"]'::jsonb, 0, '筒に立った四本の突起に毛糸を掛け、専用の針ですくって編んでいく。長さを競っては筆箱にしまい、たいてい何にもならずに終わった。', '小学校', 'female'),
  ('交換日記で、いちばんやってはいけない行為とされたのは？', '["返事を書かずに何日も持ったままにすること", "ボールペンで書くこと", "イラストを描くこと", "三人以上でやること"]'::jsonb, 0, 'ノートが自分のところで止まると、それだけで友情が疑われた。休み時間に机の中へそっと戻すのが作法で、先生に見つかると没収された。', '小学校', 'female'),
  ('雑誌「明星」「平凡」に毎号ついてきた付録の中身は？', '["ヒット曲の歌詞を集めた歌本", "アイドルのサイン色紙", "一年分のカレンダー", "缶バッジ"]'::jsonb, 0, '明星は「YOUNG SONG（ヤンソン）」、平凡は「SONG BOOK」。テレビの前で歌詞を追いかけるうち、表紙から先にボロボロになった。', '中学校', 'female'),
  ('「りぼん」「なかよし」のふろくを使い始める前に、必ず必要だったのは？', '["切り取って、のりやセロテープで組み立てること", "水につけて転写すること", "アイロンをかけること", "電池を入れること"]'::jsonb, 0, '紙の型紙をミシン目に沿って外し、便箋入れや小物入れに組み立てる。うまく折れずに歪んだ箱でも、大切に机の引き出しへ並べていた。', '小学校', 'female'),
  ('テストで答えが分からないとき、六角形の鉛筆でやっていたことは？', '["各面に番号を書いて転がし、出た数字を答えにした", "削って芯の色で占った", "立てて倒れた方向で決めた", "消しゴムに聞いた"]'::jsonb, 0, '三択なら1から3、四択なら1から4。休み時間に前もって書き込んでおくのがコツで、実際に当たってしまったときの気まずさもセットだった。', '中学校', 'female'),
  ('好きな人と両想いになる定番のおまじない。消しゴムをどう使った？', '["好きな人の名前を書き、誰にも見られずに使い切る", "名前を書いて土に埋める", "名前を書いて半分に割る", "名前を書いて枕の下に置く"]'::jsonb, 0, '途中で誰かに見られたら効果が消えるとされ、包み紙で名前を隠しながら使った。占い雑誌「マイバースデイ」が火をつけた文化だった。', '中学校', 'female'),
  ('「こっくりさん」で使った道具の組み合わせは？', '["十円玉と、五十音や鳥居を書いた紙", "鉛筆と方眼紙", "手鏡とろうそく", "割り箸と塩"]'::jsonb, 0, '数人で十円玉に指を乗せ、質問すると勝手に動き出す。途中でやめてはいけないと言われ、泣き出す子が出て学級会になった学校もあった。', '小学校', 'female'),
  ('ゴム跳び（ゴム段）で、いちばん高い最終段はどこの高さだった？', '["両手を上げた頭の上", "肩", "腰", "ひざ"]'::jsonb, 0, '足首から始まって、膝、腰、肩、そしてバンザイの高さまで。跳ぶのではなく足を引っかけて越えるので、スカートの下は必ず体操着だった。', '小学校', 'female'),
  ('文具店で買ったアイドルの下敷きは、授業中どう使われた？', '["ノートの下に敷いて、こっそり眺めた", "窓ガラスに貼った", "給食のトレーにした", "先生に見せて自慢した"]'::jsonb, 0, '表面がツルツルで書きにくいのに、みんな使っていた。角度を変えると絵柄が変わるものもあり、休み時間の見せ合いが日課だった。', '中学校', 'female'),
  ('文通相手（ペンフレンド）は、どこで見つけるのが普通だった？', '["少女雑誌の文通コーナーに載った住所へ手紙を出した", "学校の掲示板", "郵便局の窓口", "ラジオ番組の抽選"]'::jsonb, 0, '本名も住所も堂々と誌面に載っていた時代。便箋を三つ折りにして切手を貼り、返事を待ってポストを毎日のぞきに行く数日間が、いちばん楽しかった。', '小学校', 'female'),
  ('サンリオなどのレターセットを、友達同士でどう扱った？', '["便箋を一枚ずつ交換して集めた", "必ず全部使い切るのがマナーだった", "封筒だけ捨てて便箋を使った", "学校で売り買いした"]'::jsonb, 0, 'セットで使うのではなく、一枚ずつばらして交換するのが女子の社交。もったいなくて誰にも手紙を書かないまま、ファイルだけが増えた。', '小学校', 'female'),
  ('1980年代前半、いわゆる「ツッパリ」の女子のスカートは？', '["くるぶしまで届く長いスカート", "膝上二十センチの短いスカート", "チェック柄のプリーツ", "ズボン"]'::jsonb, 0, '今とは真逆で、長いほど不良の証だった。校門の前で先生が丈を測り、スカートを折り上げて帰る子と伸ばして帰る子で朝夕が逆になった。', '中学校', 'female'),
  ('缶製の筆箱が学校でしばしば問題になった理由は？', '["落とすと教室じゅうに響く大音量がした", "磁石で黒板にくっついた", "中身が錆びた", "燃えやすかった"]'::jsonb, 0, '静かな授業中にガシャーンと落ちると、教室じゅうの視線が一斉に集まる。それでもアイドルやキャラクターの絵柄が可愛くて、誰も布の筆箱には戻らなかった。', '小学校', 'female'),
  ('アニメ「キャンディ・キャンディ」の主題歌。キャンディが「気にしないわ」と歌ったのは？', '["そばかす", "ひとりぼっち", "泣きむし", "はだしの足"]'::jsonb, 0, '「そばかすなんて気にしないわ」から始まる歌を、女の子は全員そらで歌えた。孤児院育ちの明るさに、金曜夜のテレビの前で泣いた。', '小学校', 'female'),
  ('少女漫画雑誌に毎号載っていた、ボールペン習字講座の広告漫画のヒロインは？', '["日ペンの美子ちゃん", "ペン子ちゃん", "習字の花子さん", "文通の洋子さん"]'::jsonb, 0, '字が汚くて悩む少女が習字講座で自信をつけ、最後は必ず恋がうまくいく。本編より先にこの一ページを読んでいた人が、実はかなり多い。', '中学校', 'female'),
  ('集めたお気に入りのシールは、どう扱うのが正解だった？', '["もったいなくて貼らず、シール帳に挟んで保管した", "すぐノートに貼った", "教科書の表紙に貼った", "下敷きに貼って持ち歩いた"]'::jsonb, 0, '使ってしまうと減るので、透明ポケットのアルバムに入れて眺めるだけ。ダブった分を交換用に分けておくのが、上級者の作法だった。', '小学校', 'female'),
  ('友達の間で回した「プロフィール帳」で、みんなが書くのをいちばん迷った欄は？', '["好きな人", "血液型", "身長", "将来の夢"]'::jsonb, 0, 'イニシャルでごまかす人、「ヒミツ」と書く人、正直に書いて大騒ぎになる人。回ってきたページの筆跡で、誰が書いたかすぐ分かった。', '中学校', 'female'),
  ('あなたたちが中学生だった頃、家庭科の授業はどうなっていた？', '["女子は家庭科、男子は技術科と分かれていた", "全員が家庭科を受けた", "選択制だった", "高校からしかなかった"]'::jsonb, 0, '女子はミシンと調理、男子は木工と電気。男女が同じ内容を学ぶのは1993年度からで、あなたたちの学年には間に合わなかった。', '中学校', 'female'),
  ('1980年代半ば、雑誌「Olive」が女子高生に示した憧れの少女像は？', '["フランスの女子高生「リセエンヌ」", "アメリカのチアリーダー", "ロンドンのパンクガール", "イタリアの令嬢"]'::jsonb, 0, '1982年創刊。1983年秋から「Magazine for Romantic Girls」を掲げ、リセエンヌ風の着こなしと部屋づくりが女子高生の教科書になった。', '高校', 'female'),
  ('1980年代末から1991年頃、若い女性の間で「クリスマスの定番」とされたのは？', '["高級ホテルのディナーと、ティファニーのオープンハート", "手作りのケーキ", "家族そろっての食事", "近所の教会でのミサ"]'::jsonb, 0, '赤坂プリンスの部屋が半年前から埋まり、開けると水色の小さな箱。バブル末期のクリスマスは、ほぼ全員参加の年中行事になっていた。', '大学・社会人', 'female')
insert into public.timeline_events (event_date, title, note, genre, gender_lean)
values
  ('1975-01-05'::date, '「フランダースの犬」放送開始', 'あなたが小学校に入る3か月前。最終回のネロとパトラッシュに、家じゅうが泣いた。', 'アニメ漫画', 'female'),
  ('1975-04-01'::date, '小学校に入学', 'あなたの小学校生活が始まった春。ランドセルは、まだ黒と赤の二択しかなかった。', '学校生活', 'male'),
  ('1975-04-05'::date, '「秘密戦隊ゴレンジャー」放送開始', 'あなたが小1になった直後。翌週から校庭は、5人組の役の取り合いで始まった。', 'テレビ', 'male'),
  ('1975-12-25'::date, '「およげ!たいやきくん」発売', 'あなたが小1の冬。ポンキッキから流れた歌を、日本中の子どもが歌っていた。', '音楽', 'female'),
  ('1976-07-17'::date, 'モントリオール五輪 開幕', 'あなたが小2の夏。全日本女子バレーの金メダルに、家族そろって拍手した。', 'スポーツ', 'female'),
  ('1976-07-27'::date, 'ロッキード事件で田中角栄前首相を逮捕', 'あなたが小2の夏休み。「ピーナッツ」という言葉を、大人が真顔で話していた。', '事件世相', 'male'),
  ('1976-08-25'::date, 'ピンク・レディー「ペッパー警部」でデビュー', 'あなたが小2の夏。振り付けを覚えて、教室でも家でも踊り続けていた。', '音楽', 'female'),
  ('1976-10-01'::date, 'アニメ「キャンディ・キャンディ」放送開始', 'あなたが小2の秋。金曜の夜、テレビの前で主題歌を一緒に歌っていた。', 'アニメ漫画', 'female'),
  ('1977-01-01'::date, 'スーパーカーブームが最高潮に', 'あなたが小3の冬。カウンタックを見るためだけに、自転車で遠くの展示会へ。', '事件世相', 'male'),
  ('1977-05-15'::date, '「コロコロコミック」創刊', 'あなたが小3の春。電話帳みたいに分厚い漫画雑誌が、教室で回し読みされた。', 'アニメ漫画', 'male'),
  ('1977-08-06'::date, '劇場版「宇宙戦艦ヤマト」公開', 'あなたが小3の夏休み。映画館に長い行列ができ、アニメの見られ方が変わった。', '映画', 'male'),
  ('1977-12-05'::date, 'ピンク・レディー「UFO」発売', 'あなたが小3の冬。手のひらを上に向けるあのポーズは、全員が完璧にできた。', '音楽', 'female'),
  ('1978-01-19'::date, '「ザ・ベストテン」放送開始', 'あなたが小3の3学期。木曜9時、順位が読み上げられる瞬間に家族が黙った。', 'テレビ', 'female'),
  ('1978-04-04'::date, 'キャンディーズが後楽園球場で解散コンサート', 'あなたが小4になった直後。「普通の女の子に戻りたい」が流行語になった。', '音楽', 'male'),
  ('1978-06-01'::date, '「スペースインベーダー」が登場', 'あなたが小4の初夏。喫茶店のテーブルが、いつのまにかゲーム機になった。', 'ゲーム玩具', 'male'),
  ('1978-06-03'::date, '「はいからさんが通る」テレビアニメ放送開始', 'あなたが小4の初夏。袴にブーツの紅緒さんが、女子の憧れになった。', 'アニメ漫画', 'female'),
  ('1978-06-30'::date, '映画「スター・ウォーズ」日本公開', 'あなたが小4の夏。宇宙を舞台にした映像に、教室の話題が一色になった。', '映画', 'male'),
  ('1979-02-09'::date, '「花の子ルンルン」放送開始', 'あなたが小4の冬。七色の花を探す旅に、日曜の朝がときめいた。', 'アニメ漫画', 'female'),
  ('1979-04-02'::date, '「ドラえもん」テレビ朝日版 放送開始', 'あなたが小5の春。それから半世紀、あの声がずっと日常の一部になった。', 'アニメ漫画', 'male'),
  ('1979-04-07'::date, '「機動戦士ガンダム」放送開始', 'あなたが小5の春。本放送では人気が出ず、爆発したのは再放送からだった。', 'アニメ漫画', 'male'),
  ('1979-06-01'::date, '「口裂け女」の噂が全国に広まる', 'あなたが小5の初夏。集団下校になった学校もあった、初めての都市伝説。', '事件世相', 'male'),
  ('1979-07-01'::date, 'ソニー「ウォークマン」発売', 'あなたが小5の夏。音楽を持ち歩くという発想が、まだ衝撃だった頃。', '事件世相', 'male'),
  ('1979-08-04'::date, '劇場版「銀河鉄道999」公開', 'あなたが小5の夏休み。ゴダイゴの主題歌とともに、初めて映画で泣いた。', '映画', 'female'),
  ('1979-08-16'::date, '高校野球 箕島対星稜が延長18回の死闘', 'あなたが小5の夏。夜まで続いた試合を、大人たちが翌日も語っていた。', 'スポーツ', 'male'),
  ('1979-10-10'::date, '「ベルサイユのばら」アニメ放送開始', 'あなたが小5の秋。オスカル様に、女子の初恋がまとめて奪われた。', 'アニメ漫画', 'female'),
  ('1979-10-26'::date, '「3年B組金八先生」放送開始', 'あなたが小5の秋。たのきんトリオが、金曜夜の教室から生まれた。', 'テレビ', 'female'),
  ('1980-04-01'::date, '松田聖子「裸足の季節」でデビュー', 'あなたが小6になった日。聖子ちゃんカットが、教室の女子を塗り替えた。', '音楽', 'female'),
  ('1980-04-28'::date, '任天堂「ゲーム&ウオッチ」発売', 'あなたが小6の春。ポケットの中で押していた、最初の携帯ゲーム機。', 'ゲーム玩具', 'male'),
  ('1980-07-01'::date, 'ガンプラ「1/144 ガンダム」発売', 'あなたが小6の夏。300円のキットを求めて、模型店に子どもの行列ができた。', 'ゲーム玩具', 'male'),
  ('1980-07-25'::date, '「ルービックキューブ」日本発売', 'あなたが小6の夏。そろわないまま、シールを剥がして貼り替えた人もいた。', 'ゲーム玩具', 'female'),
  ('1980-08-01'::date, '甲子園で早実1年・荒木大輔がフィーバー', 'あなたが小6の夏。女子高生が甲子園に押し寄せた、最初のアイドル球児。', 'スポーツ', 'female'),
  ('1980-10-05'::date, '山口百恵が日本武道館でラストコンサート', 'あなたが小6の秋。マイクを置いて去る背中を、家族全員で見つめていた。', '音楽', 'female'),
  ('1980-11-04'::date, '王貞治が現役引退を表明', 'あなたが小6の秋。「王選手のいない野球」が、どうしても想像できなかった。', 'スポーツ', 'male'),
  ('1981-03-31'::date, 'ピンク・レディーが後楽園球場で解散', 'あなたが小6の春休み。雨の中の解散コンサートで、ひとつの時代が閉じた。', '音楽', 'female'),
  ('1981-04-01'::date, '中学校に入学', 'あなたが中学生になった春。校則と部活と、丸刈りやブルマの3年間が始まった。', '学校生活', 'male'),
  ('1981-04-01'::date, '「なめ猫」の免許証が爆発的に売れる', 'あなたが中1の頃。「なめんなよ」の子猫を、下敷きに挟んで持ち歩いた。', 'ゲーム玩具', 'female'),
  ('1981-04-08'::date, '「Dr.スランプ アラレちゃん」放送開始', 'あなたが中1の春。「んちゃ」と「バイちゃ」が、学校中の挨拶になった。', 'アニメ漫画', 'male'),
  ('1981-04-23'::date, '初代タイガーマスクがデビュー', 'あなたが中1の春。金曜8時のプロレスが、空中殺法で塗り替えられた。', 'スポーツ', 'male'),
  ('1981-05-16'::date, '「オレたちひょうきん族」放送開始', 'あなたが中1の春。土曜8時をドリフにするか、ひょうきん族にするかで揉めた。', 'テレビ', 'male'),
  ('1981-10-09'::date, '「北の国から」放送開始', 'あなたが中1の秋。純と蛍という名前が、この年から一気に増えていった。', 'テレビ', 'female'),
  ('1981-10-14'::date, '「うる星やつら」放送開始', 'あなたが中1の秋。ラムちゃんが、男子の理想像を根こそぎ書き換えた。', 'アニメ漫画', 'male'),
  ('1981-12-19'::date, '映画「セーラー服と機関銃」公開', 'あなたが中1の冬。薬師丸ひろ子の「快感」の一言が、教室で真似された。', '映画', 'female'),
  ('1982-02-08'::date, 'ホテルニュージャパン火災', 'あなたが中2の冬。翌日には日航機の羽田沖墜落が続き、テレビが暗かった。', '事件世相', 'male'),
  ('1982-05-01'::date, '中森明菜「スローモーション」でデビュー', 'あなたが中2になったばかりの春。「少女A」はこの年の7月28日だった。', '音楽', 'female'),
  ('1982-05-05'::date, 'シブがき隊「NAI・NAI 16」でデビュー', 'あなたが中2の春。たのきんの次は、フックン・ヤックン・モックンだった。', '音楽', 'female'),
  ('1982-06-03'::date, '雑誌「Olive」創刊', 'あなたが中2の初夏。「リセエンヌ」という言葉を、この雑誌で初めて知った。', '事件世相', 'female'),
  ('1982-07-01'::date, '「ときめきトゥナイト」が「りぼん」で連載開始', 'あなたが中2の夏。蘭世と真壁くんに、少女漫画の全盛期が重なった。', 'アニメ漫画', 'female'),
  ('1982-10-04'::date, '「笑っていいとも!」放送開始', 'あなたが中2の秋。昼に見ていた人は、たいてい学校を休んでいた日だった。', 'テレビ', 'female'),
  ('1982-12-04'::date, '映画「E.T.」日本公開', 'あなたが中2の冬。自転車が月をよぎる場面で、館内が静かにどよめいた。', '映画', 'female'),
  ('1983-02-11'::date, '「金曜日の妻たちへ」放送開始', 'あなたが中3の冬。大人の恋愛という世界が、金曜の夜に開いていた。', 'テレビ', 'female'),
  ('1983-04-03'::date, 'アニメ「キン肉マン」放送開始', 'あなたが中3の春。消しゴムを指で弾く遊びが、また教室に戻ってきた。', 'アニメ漫画', 'male'),
  ('1983-04-15'::date, '東京ディズニーランド開園', 'あなたが中3の春。修学旅行や卒業旅行の行き先が、この日から変わった。', '事件世相', 'female'),
  ('1983-05-27'::date, '「ふぞろいの林檎たち」放送開始', 'あなたが中3の春。三流大学生の焦りが、なぜか自分ごとに思えてしまった。', 'テレビ', 'male'),
  ('1983-07-01'::date, '「魔法の天使クリィミーマミ」放送開始', 'あなたが中3の夏。魔法少女がアイドルになるという発明に、夢中になった。', 'アニメ漫画', 'female'),
  ('1983-07-15'::date, 'ファミリーコンピュータ発売', 'あなたが中3の夏。14800円。受験の年に、家へやって来た最大の誘惑。', 'ゲーム玩具', 'male'),
  ('1983-08-21'::date, 'PL学園が夏の甲子園で優勝、1年生KKコンビ登場', 'あなたが中3の夏。1年生の桑田と清原に、同世代の物差しが狂った。', 'スポーツ', 'male'),
  ('1983-09-21'::date, 'チェッカーズ「ギザギザハートの子守唄」でデビュー', 'あなたが中3の秋。翌年には、学校中がチェッカーズの髪型になった。', '音楽', 'female'),
  ('1983-12-01'::date, '尾崎豊「十七歳の地図」でデビュー', 'あなたが中3の冬。まだ誰も知らないその歌が、数年後に深く刺さる。', '音楽', 'male'),
  ('1984-03-11'::date, '映画「風の谷のナウシカ」公開', 'あなたが中3の3月。卒業式のあと、友達と観に行った人も多かった。', '映画', 'female'),
  ('1984-03-18'::date, 'グリコ・森永事件が始まる', 'あなたが中3の3月。「かい人21面相」に、日本中が1年以上振り回された。', '事件世相', 'male')
insert into public.timeline_events (event_date, title, note, genre, gender_lean)
values
  ('1984-04-01'::date, '高校に入学', 'あなたの高校生活が始まった春。制服、部活、そして初めてのアルバイト。', '学校生活', 'female'),
  ('1984-08-11'::date, 'ロサンゼルス五輪 山下泰裕が柔道で金メダル', 'あなたが高1の夏。足を引きずって畳に上がる姿に、テレビの前で拳を握った。', 'スポーツ', 'male'),
  ('1984-10-06'::date, '「スクール☆ウォーズ」放送開始', 'あなたが高1の秋。「おまえら、それでも男か!」が本気で心に刺さった。', 'テレビ', 'male'),
  ('1984-11-20'::date, '「ドラゴンボール」が週刊少年ジャンプで連載開始', 'あなたが高1の秋。まだ悟空に尻尾があった、冒険漫画だった頃の話。', 'アニメ漫画', 'male'),
  ('1985-03-17'::date, 'つくば科学万博 開幕', 'あなたが高1の3月。ロボットと未来を見に、友達と出かけた人もいた。', '事件世相', 'male'),
  ('1985-03-24'::date, 'アニメ「タッチ」放送開始', 'あなたが高1の3月。南ちゃんと上杉兄弟に、青春の物差しをもらった。', 'アニメ漫画', 'female'),
  ('1985-04-01'::date, '「夕やけニャンニャン」放送開始、おニャン子クラブ誕生', 'あなたが高2の春。同い年くらいの素人が、アイドルになる時代が来た。', 'テレビ', 'male'),
  ('1985-04-11'::date, '「スケバン刑事」放送開始', 'あなたが高2の春。斉藤由貴のヨーヨーを、休み時間に真似した人がいた。', 'テレビ', 'female'),
  ('1985-07-05'::date, 'おニャン子クラブ「セーラー服を脱がさないで」発売', 'あなたが高2の夏。歌詞に赤面しながら、しっかり全部覚えていた。', '音楽', 'male'),
  ('1985-08-01'::date, 'ビックリマン「悪魔VS天使シール」第1弾が発売', 'あなたが高2の夏。弟や妹が箱買いしていた、あのキラキラ光るシール。', 'ゲーム玩具', 'male'),
  ('1985-08-12'::date, '日本航空123便 墜落事故', 'あなたが高2の夏休み。お盆前の速報を、いまも鮮明に覚えている人が多い。', '事件世相', 'female'),
  ('1985-09-13'::date, '「スーパーマリオブラザーズ」発売', 'あなたが高2の秋。受験期なのに、無限1UPだけは完璧にできるようになった。', 'ゲーム玩具', 'male'),
  ('1985-09-28'::date, '「8時だョ!全員集合」放送終了', 'あなたが高2の秋。16年続いた土曜8時が、静かに幕を下ろした。', 'テレビ', 'female'),
  ('1985-11-02'::date, '阪神タイガースが日本一', 'あなたが高2の秋。道頓堀に人が次々と飛び込んだ、あの騒がしい秋。', 'スポーツ', 'male'),
  ('1985-12-12'::date, '少年隊「仮面舞踏会」でデビュー', 'あなたが高2の冬。バク転しながら歌うアイドルに、悲鳴が上がった。', '音楽', 'female'),
  ('1985-12-14'::date, '映画「ビー・バップ・ハイスクール」公開', 'あなたが高2の冬。学ランを改造した先輩が、実際にすぐ近くにいた。', '映画', 'male'),
  ('1986-04-01'::date, '男女雇用機会均等法 施行', 'あなたが高3の春。「働き続ける」という選択が、法律で開かれた最初の学年。', '事件世相', 'female'),
  ('1986-04-08'::date, 'アイドル・岡田有希子さんが死去', 'あなたが高3の春。過熱する報道に、初めてテレビへの薄気味悪さを感じた。', '事件世相', 'female'),
  ('1986-04-26'::date, 'チェルノブイリ原発事故', 'あなたが高3の春。遠い国の事故が、雨や野菜の話として身近になった。', '事件世相', 'male'),
  ('1986-05-27'::date, '「ドラゴンクエスト」発売', 'あなたが高3の春。受験の年に、ふっかつのじゅもんを書き写す日々が始まった。', 'ゲーム玩具', 'male'),
  ('1986-07-25'::date, '「男女7人夏物語」放送開始', 'あなたが高3の夏。さんまと大竹しのぶの掛け合いで、恋愛の間合いを学んだ。', 'テレビ', 'female'),
  ('1987-01-24'::date, '共通一次試験を受験', 'あなたが高3の1月。2日間のマークシートに、人生で初めて本気で震えた。', '学校生活', 'male'),
  ('1987-03-01'::date, '高校を卒業', 'あなたの高校生活が終わった春。第二ボタンも、寄せ書きも、この日の話。', '学校生活', 'female'),
  ('1987-04-01'::date, '国鉄が分割民営化され、JRが発足', 'あなたが18歳の春。「国鉄」という言葉が、この日から過去形になった。', '事件世相', 'male'),
  ('1987-04-01'::date, '大学に入学、または社会人1年目が始まる', 'あなたが18歳の春。進路が分かれ、同級生の景色が初めてバラバラになった。', '学校生活', 'female'),
  ('1987-08-19'::date, '光GENJI「STAR LIGHT」でデビュー', 'あなたが19歳の夏。ローラースケートのアイドルに、妹世代が熱狂した。', '音楽', 'female'),
  ('1987-10-03'::date, '「ねるとん紅鯨団」放送開始', 'あなたが19歳の秋。「ちょっといいですか」が、合コンの公式作法になった。', 'テレビ', 'male'),
  ('1987-11-21'::date, '映画「私をスキーに連れてって」公開', 'あなたが19歳の秋。この一本で、冬はスキー場に行くものだと決まった。', '映画', 'female'),
  ('1988-02-10'::date, '「ドラゴンクエストIII」発売', 'あなたが19歳の冬。徹夜の行列と補導の騒ぎが、全国ニュースになった。', 'ゲーム玩具', 'male'),
  ('1988-04-05'::date, 'BOOWYが東京ドームで解散ライブ', 'あなたが20歳の春。バンドをやっていた友人が、本気で落ち込んでいた。', '音楽', 'male'),
  ('1988-04-16'::date, '「となりのトトロ」「火垂るの墓」同時公開', 'あなたが20歳の春。当時は大ヒットしなかったことを、覚えている人は少ない。', '映画', 'female'),
  ('1988-06-18'::date, 'リクルート事件が報じられる', 'あなたが20歳の初夏。就職を考え始めた年に、就職情報会社の名が汚職で出た。', '事件世相', 'male'),
  ('1988-09-24'::date, 'ソウル五輪 鈴木大地が競泳で金メダル', 'あなたが20歳の秋。「バサロ泳法」という言葉を、日本中が一日で覚えた。', 'スポーツ', 'male'),
  ('1989-01-07'::date, '昭和天皇が崩御、昭和が終わる', 'あなたが20歳の冬。テレビからCMが消え、街から音が消えた一週間だった。', '事件世相', 'male'),
  ('1989-01-08'::date, '元号が「平成」に改まる', 'あなたが20歳の冬。掲げられた2文字を、教室でも職場でも黙って見ていた。', '事件世相', 'female'),
  ('1989-01-15'::date, 'あなたたちの成人式', '昭和天皇崩御のわずか8日後。自粛ムードの中で晴れ着を着た、特別な学年。', '学校生活', 'female'),
  ('1989-02-11'::date, '「いかすバンド天国（イカ天）」放送開始', 'あなたが20歳の冬。深夜番組から、バンドブームが一気に爆発していった。', 'テレビ', 'male'),
  ('1989-04-01'::date, '消費税3%が導入される', 'あなたが20歳の春。財布に1円玉がたまり始めた、あの春のこと。', '事件世相', 'female'),
  ('1989-04-21'::date, '「ゲームボーイ」発売', 'あなたが21歳の春。テトリスを、通学電車で延々やっていた人がいる。', 'ゲーム玩具', 'male'),
  ('1989-07-05'::date, 'Wink「淋しい熱帯魚」発売', 'あなたが21歳の夏。笑わないアイドルが、カラオケの定番になっていった。', '音楽', 'female'),
  ('1989-07-29'::date, '映画「魔女の宅急便」公開', 'あなたが21歳の夏。13歳のキキの独り立ちが、就職前の自分に重なった。', '映画', 'female'),
  ('1989-11-09'::date, 'ベルリンの壁が崩壊', 'あなたが21歳の秋。世界が変わる瞬間を、生中継で見た最初の世代。', '事件世相', 'male'),
  ('1989-12-29'::date, '日経平均が史上最高値38915円をつける', 'あなたが21歳の冬。この日が頂点だったと、まだ誰も知らなかった。', '事件世相', 'male'),
  ('1990-01-07'::date, 'アニメ「ちびまる子ちゃん」放送開始', 'あなたが21歳の冬。まる子の昭和が、あなたの子ども時代そのものだった。', 'アニメ漫画', 'female'),
  ('1990-01-13'::date, '第1回 大学入試センター試験', 'あなたが大学3年の冬。共通一次を受けたあなたの、3学年下から名前が変わった。', '学校生活', 'female'),
  ('1990-10-01'::date, '日経平均が2万円を割り、バブル崩壊が始まる', 'あなたが大学4年の秋。内定を持ったまま、景気の潮目が静かに変わっていった。', '事件世相', 'male'),
  ('1990-11-21'::date, '「スーパーファミコン」発売', 'あなたが22歳の秋。就職を決めた年に、また新しい本体が出てしまった。', 'ゲーム玩具', 'male'),
  ('1991-01-07'::date, '「東京ラブストーリー」放送開始', 'あなたが大学4年の冬。カンチとリカに、社会へ出る直前の恋愛観を作られた。', 'テレビ', 'female'),
  ('1991-01-17'::date, '湾岸戦争が始まる', 'あなたが22歳の冬。卒業直前、深夜の空爆中継を見ながら卒論を書いた。', '事件世相', 'male'),
  ('1991-02-06'::date, '小田和正「ラブ・ストーリーは突然に」発売', 'あなたが22歳の冬。270万枚。あの前奏だけで、1991年に戻れてしまう。', '音楽', 'female'),
  ('1991-04-01'::date, '大学を卒業して入社、バブル最末期の入社式', 'あなたが22歳の春。売り手市場の最後の年。同期の人数が異常に多かった。', '学校生活', 'male'),
  ('1991-05-15'::date, '「ジュリアナ東京」が芝浦にオープン', 'あなたが社会人1年目の春。お立ち台とボディコンが、時代の象徴になった。', '事件世相', 'female'),
  ('1991-07-01'::date, '「101回目のプロポーズ」放送開始', 'あなたが社会人1年目の夏。「僕は死にましぇん」を、飲み会で誰かが必ずやった。', 'テレビ', 'female'),
  ('1991-07-24'::date, 'CHAGE and ASKA「SAY YES」発売', 'あなたが社会人1年目の夏。ミリオンセラーが当たり前になる時代へ入った。', '音楽', 'male'),
  ('1993-05-15'::date, 'Jリーグ開幕', 'あなたが25歳の春。国立競技場の開幕戦を、翌日の職場で語り合った。', 'スポーツ', 'male'),
  ('1995-01-17'::date, '阪神・淡路大震災', 'あなたが26歳の冬。同世代が被災し、初めて「自分たちの番」を実感した。', '事件世相', 'female'),
  ('1995-11-23'::date, 'Windows 95 日本語版 発売', 'あなたが27歳の冬。会社にパソコンが入り、仕事の作法が変わり始めた。', '事件世相', 'male'),
  ('2011-03-11'::date, '東日本大震災', 'あなたが42歳の春。働き盛りで、家族と仕事の両方を背負っていた年。', '事件世相', 'female'),
  ('2019-05-01'::date, '元号が「令和」に改まる', 'あなたが51歳の春。昭和・平成・令和の3つを生きる学年になった。', '事件世相', 'female'),
  ('2026-04-01'::date, '昭和43年度生まれが57歳・58歳になる年度', 'あなたの今。定年も親の介護も、同じ速さで近づいてくる歳になった。', '事件世相', 'female')
