-- 2026-08-05、参加ハードル最小化リニューアルの初期コンテンツ投入。
-- 二択投票60本、穴埋めお題60本、検定40問、年表120件、企画記事3本。
-- 公開直後に「回答0件」を晒さないため、一部は公開済み、残りは週2本ずつ自動公開されるよう
-- published_at を未来日付で仕込んでいる。

-- ===== 00_retire_weak_topics.sql =====

update public.topics t
set is_active = false
where t.created_at < '2026-08-05'
  and not exists (
    select 1 from public.topic_responses r where r.topic_id = t.id
  );

